SELECT city, CASE WHEN credit_limit >= 15800 THEN 'HIGH' ELSE 'LOW' END AS credit_limit_tier, COUNT_IF(city = 'Bangkok') AS bangkok_events, ROUND(SUM(age) / NULLIF(COUNT(CASE WHEN country = 'US' THEN 1 END), 0), 2) AS age_per_us, PERCENTILE_APPROX(credit_limit, 0.9) AS credit_limit_p90, STDDEV_SAMP(credit_limit) AS credit_limit_stddev, SIZE(COLLECT_SET(country)) AS num_countries, COUNT(CASE WHEN country = 'US' THEN 1 END) AS us_count FROM customers GROUP BY CUBE (city, CASE WHEN credit_limit >= 15800 THEN 'HIGH' ELSE 'LOW' END) ORDER BY city DESC;
